def cesar(texto, chave):
    saida = ''
    for c in texto:
        if c.isalpha():
            base = ord('A') if c.isupper() else ord('a')
            saida += chr((ord(c) - base + chave) % 26 + base)
        else:
            saida += c
    return saida

