    tabela = [(1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]
    saida = ''
    for valor, s in tabela:
        while n >= valor:
            saida += s
            n -= valor
    return saida

def mediana(lista):
    if not lista:
        return 0
    ord = sorted(lista)
    n = len(ord)
    if n % 2 == 1:
        return ord[n // 2]
    return (ord[n // 2 - 1] + ord[n // 2]) / 2

