def validar_cpf(cpf):
    n = [int(c) for c in cpf if c.isdigit()]
    if len(n) != 11 or len(set(n)) == 1:
        return False
    for i in (9, 10):
        s = sum(n[j] * (i + 1 - j) for j in range(i))
        d = (s * 10 % 11) % 10
        if d != n[i]:
            return False
    return True

