def palindromo(s):
    s = ''.join(c.lower() for c in s if c.isalnum())
    return s == s[::-1]

def em_ordem(no):
    if no:
        yield from em_ordem(no.esquerda)
        yield no.valor
        yield from em_ordem(no.direita)

def potencia(base, exp):
    resultado = 1
    for _ in range(exp):
        resultado *= base
    return resultado

import time

def tentar(func, tentativas=3, espera=1):
    for i in range(tentativas):
        try:
            return func()
        except Exception:
            if i == tentativas - 1:
                raise
            time.sleep(espera)

