class Fila:
    def __init__(self):
        self.items = []
    def enfileirar(self, item):
        self.items.append(item)
    def desenfileirar(self):
        if not self.items:
            return None
        return self.items.pop(0)
    def vazia(self):
        return len(self.items) == 0
